//! Account sync excludes device grants, paths, credentials and memory.
use serde_json::{json,Value};
const KEYS:&[&str]=&["rsProfilePicture","rsLanguage","rsWorkMode","rsThinkingLevel","rsSounds","rsExtraThinking","rsShowApproach","rsPlanMode","rsAppearance","rsVisualCheck","rsContinuationOffer","rsInputLimitEnabled","rsInputCharLimit","rsOutputLimitEnabled","rsOutputCharLimit","rsForgeMode","rsAutoFix"];
static SERIAL:tokio::sync::Mutex<()>=tokio::sync::Mutex::const_new(());
static STATUS:once_cell::sync::Lazy<std::sync::RwLock<std::collections::BTreeMap<String,String>>>=once_cell::sync::Lazy::new(Default::default);
pub fn status(id:&str)->String{STATUS.read().unwrap_or_else(|e|e.into_inner()).get(id).cloned().unwrap_or_else(||"Waiting to sync".into())}
// The account service keeps the look as theme, glow and gradients only (account-service/lib/protocol.js is strict). The
// app's Feel (motion, animated theme, click effects; 1.24.33) stays on this computer: it is left out of what is sent and
// put back from this computer's preferences before the synced look is applied.
const FEEL:&[&str]=&["motion","anim","ripple"];
fn portable_appearance(value:&Value)->Value{Value::Object(value.as_object().into_iter().flatten().filter(|(key,_)|!FEEL.contains(&key.as_str())).map(|(k,v)|(k.clone(),v.clone())).collect())}
fn settings(value:Value)->Value{let mut out:serde_json::Map<String,Value>=value.as_object().into_iter().flatten().filter(|(key,_)|KEYS.contains(&key.as_str())).map(|(k,v)|(k.clone(),v.clone())).collect();if let Some(look)=out.get("rsAppearance").filter(|v|v.is_object()).cloned(){out.insert("rsAppearance".into(),portable_appearance(&look));}Value::Object(out)}
fn with_feel(settings:&Value,device:&Value)->Value{let mut out=settings.clone();if let Some(look)=out.get_mut("rsAppearance").and_then(Value::as_object_mut){for key in FEEL{if let Some(v)=device.get(*key){look.insert((*key).into(),v.clone());}}}out}
fn merge(base:&Value,local:&Value,remote:&Value)->Value{let mut out=remote.as_object().cloned().unwrap_or_default();let keys:std::collections::BTreeSet<_>=base.as_object().into_iter().flatten().map(|(k,_)|k).chain(local.as_object().into_iter().flatten().map(|(k,_)|k)).collect();for key in keys{if base.get(key)!=local.get(key){if let Some(v)=local.get(key){out.insert(key.clone(),v.clone());}else{out.remove(key);}}}Value::Object(out)}
async fn snapshot(state:&crate::AppState)->anyhow::Result<Value>{let mut portable=settings(serde_json::to_value(state.preferences.snapshot())?);let active=state.accounts.active().ok_or_else(||anyhow::anyhow!("Sign in first"))?;portable["rsProfilePicture"]=crate::profile_picture::read(&active.id)?;Ok(json!({"settings":portable,"skills":crate::skills::account_export().await?}))}
pub async fn run(state:&crate::AppState)->anyhow::Result<()>{let _serial=SERIAL.lock().await;let Some(active)=state.accounts.active()else{return Ok(())};if active.guest{STATUS.write().unwrap_or_else(|e|e.into_inner()).insert(active.id,"Guest · saved on this computer".into());return Ok(());}let result=sync(state).await;STATUS.write().unwrap_or_else(|e|e.into_inner()).insert(active.id.clone(),if result.is_ok(){"Up to date"}else{"Offline or unable to sync — changes are saved on this computer"}.into());let appearance=serde_json::to_value(state.preferences.snapshot())?["rsAppearance"].clone();let _=state.accounts.cache_appearance(appearance).await;result}
async fn sync(state:&crate::AppState)->anyhow::Result<()>{let path=crate::profile_paths::data_root().join("account-sync.json");let local=snapshot(state).await?;let mut baseline=match std::fs::read(&path){Ok(bytes)=>serde_json::from_slice::<Value>(&bytes)?,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>{let mut defaults=settings(serde_json::to_value(crate::preferences::DesktopPreferences::default())?);defaults["rsProfilePicture"]=Value::Null;json!({"settings":defaults,"skills":{}})},Err(e)=>return Err(e.into())};
 if let Some(settings)=baseline.get_mut("settings").and_then(Value::as_object_mut){settings.entry("rsProfilePicture").or_insert(Value::Null);}
 for _ in 0..3{let remote=state.accounts.cloud_read().await?;let document=&remote["document"];anyhow::ensure!(document["settings"].is_object()&&document["skills"].is_object(),"Invalid cloud document");let merged=json!({"settings":merge(&baseline["settings"],&local["settings"],&settings(document["settings"].clone())),"skills":merge(&baseline["skills"],&local["skills"],&document["skills"])});crate::skills::validate_account_document(&merged["skills"])?;
 if merged!=*document{match state.accounts.cloud_write(remote["revision"].as_u64().ok_or_else(||anyhow::anyhow!("Invalid sync revision"))?,merged.clone()).await{Ok(_)=>{},Err(e)if e.downcast_ref::<crate::accounts::AccountError>().is_some_and(|e|e.status==409)=>continue,Err(e)=>return Err(e)}}
 let active=state.accounts.active().ok_or_else(||anyhow::anyhow!("Sign in first"))?;crate::profile_picture::apply_if_unchanged(&active.id,&local["settings"]["rsProfilePicture"],&merged["settings"]["rsProfilePicture"])?;
 let device=serde_json::to_value(state.preferences.snapshot())?["rsAppearance"].clone();state.preferences.patch_if_unchanged(&with_feel(&local["settings"],&device),&with_feel(&merged["settings"],&device))?;crate::skills::account_apply(&local["skills"],&merged["skills"]).await?;let temporary=path.with_extension("json.tmp");std::fs::write(&temporary,serde_json::to_vec(&merged)?)?;if path.exists(){std::fs::remove_file(&path)?;}std::fs::rename(temporary,path)?;return Ok(());}anyhow::bail!("Account changed on another device; sync will retry")}
#[cfg(test)]mod tests{use super::*;#[test]fn merge_preserves_remote_edits_and_local_deletions(){assert_eq!(merge(&json!({"a":1,"b":1,"deleted":1}),&json!({"a":2,"b":1,"new":3}),&json!({"a":1,"b":2,"deleted":1,"remote":4})),json!({"a":2,"b":2,"new":3,"remote":4}));assert_eq!(merge(&json!({"a":1}),&json!({"a":1}),&json!({})),json!({}));}#[test]fn excludes_device_grants_paths_and_secrets(){assert_eq!(settings(json!({"rsLanguage":"fr","rsPermMode":"full","rsAllowedFolders":["/private"],"token":"secret","rsApprovalMode":"bypass"})),json!({"rsLanguage":"fr"}));}
#[test]fn the_feel_stays_on_this_computer(){let sent=settings(json!({"rsAppearance":{"theme":"cyan","glow":"off","gradients":"on","motion":"reduced","anim":false,"ripple":true}}));assert_eq!(sent,json!({"rsAppearance":{"theme":"cyan","glow":"off","gradients":"on"}}));
 let device=json!({"theme":"cyan","glow":"off","gradients":"on","motion":"reduced","anim":false,"ripple":true});assert_eq!(with_feel(&json!({"rsAppearance":{"theme":"rose","glow":"subtle","gradients":"off"},"rsLanguage":"de"}),&device),json!({"rsAppearance":{"theme":"rose","glow":"subtle","gradients":"off","motion":"reduced","anim":false,"ripple":true},"rsLanguage":"de"}));
 assert_eq!(with_feel(&json!({"rsLanguage":"de"}),&device),json!({"rsLanguage":"de"}));}}
